#### Example 1: Global Scope Pollution Test

_[To be completed]_

```typescript
// Test for global scope pollution
describe('Extension Global Scope Isolation', () => {
  let initialWindowKeys: string[];

  beforeEach(() => {
    initialWindowKeys = Object.keys(window);
  });

  it('does not pollute global window object', () => {
    // Load extension
    render(<ClaimsValidatorExtension />);

    // Check for new global variables
    const currentWindowKeys = Object.keys(window);
    const newKeys = currentWindowKeys.filter(k => !initialWindowKeys.includes(k));

    // Allow React DevTools and expected framework keys
    const unexpectedKeys = newKeys.filter(k =>
      !k.startsWith('__REACT_') &&
      !k.startsWith('__webpack_')
    );

    expect(unexpectedKeys).toHaveLength(0);
  });

  it('cleans up event listeners on unmount', () => {
    const { unmount } = render(<ClaimsValidatorExtension />);

    const initialListenerCount = getEventListeners(document).length;
    unmount();
    const finalListenerCount = getEventListeners(document).length;

    expect(finalListenerCount).toBeLessThanOrEqual(initialListenerCount);
  });
});
