#### Example 2: CSS Isolation Test

_[To be completed]_

```typescript
// Test for CSS isolation
import { render } from '@testing-library/react';

test('extension styles do not leak to host', () => {
  const { container } = render(<ClaimsValidatorExtension />);

  // Get computed styles from extension
  const extensionElement = container.querySelector('[data-extension]');
  const extensionStyles = window.getComputedStyle(extensionElement);

  // Get computed styles from host element
  const hostElement = document.querySelector('[data-host]');
  const hostStyles = window.getComputedStyle(hostElement);

  // Verify extension-specific styles don't affect host
  expect(hostStyles.color).not.toBe(extensionStyles.color);
  expect(hostStyles.fontFamily).not.toBe(extensionStyles.fontFamily);
});

test('extension uses scoped CSS classes', () => {
  const { container } = render(<ClaimsValidatorExtension />);

  const elements = container.querySelectorAll('*');
  elements.forEach(el => {
    const classes = Array.from(el.classList);
    // Check all classes are either scoped or from design system
    classes.forEach(className => {
      expect(
        className.startsWith('extension-') ||
        className.startsWith('ds-') // design system prefix
      ).toBe(true);
    });
  });
});
