#### Example 3: Memory Leak Detection Test

_[To be completed]_

```typescript
// Playwright test for memory leaks
import { test, expect } from '@playwright/test';

test('extension does not leak memory', async ({ page }) => {
  await page.goto('http://localhost:3000/claims');

  // Get initial memory usage
  const initialMemory = await page.evaluate(() => {
    if (performance.memory) {
      return performance.memory.usedJSHeapSize;
    }
    return 0;
  });

  // Load and unload extension multiple times
  for (let i = 0; i < 10; i++) {
    await page.locator('[data-load-extension]').click();
    await page.waitForSelector('[data-extension="texas-claims"]');
    await page.locator('[data-unload-extension]').click();
    await page.waitForSelector('[data-extension="texas-claims"]', { state: 'detached' });
  }

  // Force garbage collection (requires --expose-gc flag)
  await page.evaluate(() => {
    if (global.gc) global.gc();
  });

  // Get final memory usage
  const finalMemory = await page.evaluate(() => {
    if (performance.memory) {
      return performance.memory.usedJSHeapSize;
    }
    return 0;
  });

  // Memory should not increase significantly
  const memoryIncrease = finalMemory - initialMemory;
  const increasePercent = (memoryIncrease / initialMemory) * 100;

  expect(increasePercent).toBeLessThan(20); // Allow 20% increase
});
```

